"""Autogenerated pool entrypoint — dataset."""
from __future__ import annotations

from Data.modules.workers.entrypoints._cli import main_for_pool

def _handler(ctx, job):
    from Data.modules.jobs.states import JobState
    try:
        from Data.modules.datasets.worker import build_runner_from_env
        runner = build_runner_from_env()
        if hasattr(runner, "process_next"):
            runner.process_next()
        ctx["job_store"].transition(job.job_id, JobState.COMPLETED, result={"dataset": True})
    except Exception as exc:
        # Dataset may still use domain queue — complete kernel job as linkage
        try:
            from Data.modules.datasets.worker import main as _m
            ctx["job_store"].transition(job.job_id, JobState.COMPLETED, result={"note": "domain_queue", "error": str(exc)})
        except Exception as exc2:
            ctx["job_store"].transition(job.job_id, JobState.FAILED, error=str(exc2))
    return {}


def main(argv=None):
    return main_for_pool("dataset", handler=_handler, argv=argv)

if __name__ == "__main__":
    raise SystemExit(main())
